### Operaciones CRUD

#### Crear (Insert)

```javascript
// Seleccionar base de datos
use academia;

// Insertar un documento
db.alumnos.insertOne({
  nombre: "Juan",
  apellido: "García",
  email: "juan@email.com",
  fecha_nacimiento: ISODate("2005-03-15"),
  activo: true,
  notas: [
    { asignatura: "Bases de datos", nota: 8.5 },
    { asignatura: "Programación", nota: 9.0 }
  ]
});

// Insertar varios documentos
db.alumnos.insertMany([
  {
    nombre: "María",
    apellido: "López",
    email: "maria@email.com",
    notas: [
      { asignatura: "Bases de datos", nota: 9.0 },
      { asignatura: "Sistemas", nota: 8.5 }
    ]
  },
  {
    nombre: "Carlos",
    apellido: "Martínez",
    email: "carlos@email.com",
    notas: []
  }
]);
```

#### Leer (Find)

```javascript
// Buscar todos los documentos
db.alumnos.find();

// Buscar con filtro
db.alumnos.find({ nombre: "Juan" });

// Buscar con operadores
db.alumnos.find({ "notas.nota": { $gte: 8 } });  // Nota >= 8

// Buscar uno
db.alumnos.findOne({ email: "juan@email.com" });

// Proyección (seleccionar campos)
db.alumnos.find({}, { nombre: 1, apellido: 1, _id: 0 });

// Ordenar
db.alumnos.find().sort({ apellido: 1 });

// Limitar
db.alumnos.find().limit(5);

// Contar
db.alumnos.countDocuments({ activo: true });
```

#### Actualizar (Update)

```javascript
// Actualizar un documento
db.alumnos.updateOne(
  { email: "juan@email.com" },
  { $set: { activo: false } }
);

// Agregar una nota a un alumno
db.alumnos.updateOne(
  { email: "juan@email.com" },
  { $push: { notas: { asignatura: "BD avanzada", nota: 7.5 } } }
);

// Actualizar varios documentos
db.alumnos.updateMany(
  { activo: true },
  { $set: { revision_pendiente: true } }
);
```

#### Eliminar (Delete)

```javascript
// Eliminar un documento
db.alumnos.deleteOne({ email: "carlos@email.com" });

// Eliminar varios
db.alumnos.deleteMany({ activo: false });
```

#### Operadores de consulta

```javascript
// $gte, $lte, $gt, $lt
db.alumnos.find({ "notas.nota": { $gte: 8, $lte: 10 } });

// $in
db.alumnos.find({ nombre: { $in: ["Juan", "María"] } });

// $and
db.alumnos.find({
  $and: [
    { "notas.nota": { $gte: 7 } },
    { activo: true }
  ]
});

// $exists
db.alumnos.find({ email: { $exists: true } });

// $regex (LIKE)
db.alumnos.find({ nombre: /Ju/ });  // Contiene 'Ju'
```

