```javascript
// 1. Crear colección e insertar
db.productos.insertMany([
  { nombre: "Portátil HP", precio: 649.99, categoria: "Informática", stock: 15 },
  { nombre: "Ratón Logitech", precio: 19.99, categoria: "Periféricos", stock: 50 },
  { nombre: "Teclado Mecánico", precio: 49.99, categoria: "Periféricos", stock: 30 },
  { nombre: "Monitor 24\"", precio: 189.99, categoria: "Informática", stock: 20 },
  { nombre: "SSD Kingston", precio: 59.99, categoria: "Almacenamiento", stock: 0 }
]);

// 2. Productos con precio > 50
db.productos.find({ precio: { $gt: 50 } });

// 3. Actualizar stock del más barato
db.productos.updateOne(
  { precio: { $eq: 19.99 } },
  { $set: { stock: 45 } }
);

// 4. Eliminar productos con stock 0
db.productos.deleteMany({ stock: 0 });

// 5. Contar por categoría
db.productos.aggregate([
  { $group: { _id: "$categoria", total: { $sum: 1 } } }
]);
```
